'use client';

import React, { useState } from 'react';
import { useWriteContract, useWaitForTransactionReceipt } from 'wagmi';
import { parseEther } from 'viem';

const ERC20_ABI = [
  {
    name: 'transfer',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [
      { name: 'recipient', type: 'address' },
      { name: 'amount', type: 'uint256' },
    ],
    outputs: [{ name: '', type: 'bool' }],
  },
] as const;

export function TokenTransferCard({ tokenAddress }: { tokenAddress: `0x${string}` }) {
  const [recipient, setRecipient] = useState('');
  const [amount, setAmount] = useState('');

  const { writeContract, data: hash, isPending } = useWriteContract();
  const { isLoading: isConfirming, isSuccess } = useWaitForTransactionReceipt({
    hash,
  });

  const handleSend = () => {
    if (!recipient || !amount) return;
    writeContract({
      address: tokenAddress,
      abi: ERC20_ABI,
      functionName: 'transfer',
      args: [recipient as `0x${string}`, parseEther(amount)],
    });
  };

  return (
    <div className="p-6 rounded-2xl bg-card border border-cardBorder space-y-4">
      <h3 className="text-lg font-bold text-white">Chuyển Token Trên Avalanche Fuji</h3>
      <input
        value={recipient}
        onChange={(e) => setRecipient(e.target.value)}
        placeholder="0x..."
        className="w-full p-3 rounded-lg bg-gray-900 border text-white"
      />
      <input
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
        placeholder="Số lượng token"
        className="w-full p-3 rounded-lg bg-gray-900 border text-white"
      />
      <button
        onClick={handleSend}
        disabled={isPending || isConfirming}
        className="w-full py-3 bg-sky-500 text-white font-bold rounded-lg"
      >
        {isPending ? 'Đang mở ví...' : isConfirming ? 'Đang xác nhận...' : 'Chuyển Token'}
      </button>
      {isSuccess && hash && (
        <p className="text-emerald-400 text-xs">Giao dịch thành công! Tx: {hash}</p>
      )}
    </div>
  );
}
